import * as THREE from 'three/webgpu';
import { color, uniform, mix, vec3, positionLocal } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'kinetic-hero-headline';

  const colors = {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const disposables = [];
  const timelines = [];

  // --- Backdrop plane with engineered vertical gradient ---
  const backdropGeo = new THREE.PlaneGeometry(7, 5.5);
  const topColor = uniform(color(colors.background));
  const bottomColor = uniform(color('#13131a'));
  const backdropMat = new THREE.MeshBasicNodeMaterial();
  const gradFactor = positionLocal.y.mul(1 / 5.5).add(0.5).clamp(0, 1);
  backdropMat.colorNode = mix(topColor, bottomColor, gradFactor);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -1.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // --- Caption kicker ---
  const captionMesh = ctx.fontAtlas.createText('NOVA ATELIER / CALIBRE PROGRAM', {
    font: 'JetBrains Mono',
    fontWeight: 700,
    emHeight: 0.09,
    letterSpacing: 0.12,
    color: colors.accent,
    align: 'center',
  });
  captionMesh.position.set(0, 1.15, 0);
  group.add(captionMesh);

  // --- Hero headline, word-split with per-word z offsets ---
  const heroText = 'TIME, MACHINED.';
  const words = heroText.split(' ');
  const heroGroup = new THREE.Group();
  heroGroup.position.set(0, 0.4, 0);
  group.add(heroGroup);

  const zOffsets = [0.12, 0.0, -0.12];
  let cursorX = 0;
  const wordMeshes = [];
  words.forEach((word, i) => {
    const wordMesh = ctx.fontAtlas.createText(word + (i < words.length - 1 ? ' ' : ''), {
      font: 'Lora',
      fontWeight: 600,
      emHeight: 0.62,
      letterSpacing: -0.01,
      color: colors.paper,
      align: 'left',
    });
    wordMesh.position.set(cursorX, 0, zOffsets[i % zOffsets.length]);
    const bbox = new THREE.Box3().setFromObject(wordMesh);
    const width = bbox.max.x - bbox.min.x;
    cursorX += width + 0.1;
    heroGroup.add(wordMesh);
    wordMeshes.push(wordMesh);
  });

  // center hero group
  const heroBBox = new THREE.Box3().setFromObject(heroGroup);
  const heroWidth = heroBBox.max.x - heroBBox.min.x;
  heroGroup.children.forEach((c) => (c.position.x -= heroWidth / 2));

  // Collect per-glyph objects for kinetic-text primitive (fallback to word meshes)
  const glyphs = [];
  heroGroup.traverse((obj) => {
    if (obj.isMesh && obj !== heroGroup) glyphs.push(obj);
  });

  // --- Accent underline rule ---
  const underlineGeo = new THREE.PlaneGeometry(2.6, 0.045);
  const underlineMat = new THREE.MeshStandardNodeMaterial();
  underlineMat.colorNode = color(colors.accent);
  underlineMat.emissiveNode = color(colors.accent).mul(1.2);
  underlineMat.roughness = 0.5;
  underlineMat.metalness = 0.3;
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(-2.6 / 2 + 0.3, -0.05, 0.05);
  underline.scale.x = 0.0001;
  group.add(underline);
  disposables.push(underlineGeo, underlineMat);

  // --- Subhead ---
  const subhead = ctx.fontAtlas.createText('Every calibre begins as a solid billet.', {
    font: 'JetBrains Mono',
    fontWeight: 400,
    emHeight: 0.2,
    letterSpacing: 0.02,
    color: colors.paper,
    align: 'center',
  });
  subhead.position.set(0, -0.65, 0);
  subhead.material && (subhead.material.opacity = 0);
  subhead.traverse((o) => {
    if (o.isMesh) {
      o.material.transparent = true;
      o.material.opacity = 0;
    }
  });
  group.add(subhead);

  // --- Lighting for machined-metal accent underline (subtle) ---
  const rimLight = new THREE.DirectionalLight(0xffffff, 0.6);
  rimLight.position.set(2, 2, 3);
  group.add(rimLight);

  // --- Apply cinematic primitive: kinetic-text ---
  const kineticParams = { staggerMs: 60, riseUnits: 0.35 };
  const kineticPrimitive = ctx.primitives['kinetic-text'];
  if (typeof kineticPrimitive === 'function') {
    kineticPrimitive(heroGroup, kineticParams);
  } else {
    // fallback manual kinetic entrance
    glyphs.forEach((g, i) => {
      g.position.y += kineticParams.riseUnits;
      g.material && (g.material.transparent = true);
      if (g.material) g.material.opacity = 0;
      const tl = gsap.to(g.position, {
        y: g.position.y - kineticParams.riseUnits,
        duration: 0.7,
        delay: (i * kineticParams.staggerMs) / 1000,
        ease: 'power3.out',
        onUpdate: () => {
          if (g.material) g.material.opacity = 1 - (g.position.y / kineticParams.riseUnits > 0 ? g.position.y / kineticParams.riseUnits : 0);
        },
      });
      timelines.push(tl);
      if (g.material) {
        const otl = gsap.to(g.material, {
          opacity: 1,
          duration: 0.7,
          delay: (i * kineticParams.staggerMs) / 1000,
          ease: 'power2.out',
        });
        timelines.push(otl);
      }
    });
  }

  const glyphCount = glyphs.length || 1;
  const lastGlyphDelay = (glyphCount * kineticParams.staggerMs) / 1000;

  // Weighted settle on hero group after last glyph lands
  heroGroup.scale.setScalar(1.04);
  const settleTl = gsap.to(heroGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    delay: lastGlyphDelay + 0.7,
    ease: 'power4.out',
  });
  timelines.push(settleTl);

  // Underline scaleX animation
  const underlineTl = gsap.to(underline.scale, {
    x: 1,
    duration: 0.5,
    delay: lastGlyphDelay + 0.7 + 0.12,
    ease: 'power2.out',
  });
  timelines.push(underlineTl);

  // Subhead fade-up
  const subOpacityTargets = [];
  subhead.traverse((o) => {
    if (o.isMesh) subOpacityTargets.push(o.material);
  });
  subhead.position.y -= 0.0; // base
  const subStartY = subhead.position.y + 0.2;
  subhead.position.y = subStartY;
  const subTl = gsap.to(subhead.position, {
    y: subStartY - 0.2,
    duration: 0.5,
    delay: 0.1,
    ease: 'power2.out',
  });
  timelines.push(subTl);
  subOpacityTargets.forEach((mat) => {
    const t = gsap.to(mat, { opacity: 1, duration: 0.5, delay: 0.1, ease: 'power2.out' });
    timelines.push(t);
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill && tl.kill());
    disposables.forEach((d) => d.dispose && d.dispose());
    group.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry && obj.geometry.dispose && obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose && m.dispose());
          else obj.material.dispose && obj.material.dispose();
        }
      }
    });
  };

  return group;
}
